      1. ௖఺1 ͷ࠷୹ڑ ཭Λ dist[1] = 0ɺͦͷଞͷ௖఺v ͷ࠷୹ڑ཭Λ dist[v] = ∞ͱॳظԽ͠·͢ɻ
      2. ࠷ ୹ڑ཭ͷߋ৽Λ N −1 ճ ܁Γฦ͠·͢ʢܦ࿏ͷ௕͞͸࠷େͰ N −1 Ͱ͋ΔͨΊʣɻ
      3. ௖఺N ͷ ࠷୹ڑ཭Λද͢ม਺ͱͯ͠ ans=dist[N] ͱ͠·͢ɻ

      4. ࣍ ʹɺෛด࿏Λݕग़͢ΔͨΊͷ௕͞ N ͷ഑ྻnegative Λ༻ҙͯ͠ɺfalse ͰॳظԽ͠·͢ɻ

      5. ࠷ ୹ ڑ ཭ͷ ߋ ৽Λ N ճ ܁ Γฦ͢ʢෛด࿏ͷ௕͞͸ ࠷ େͰ N Ͱ͋ΔͨΊʣɻͨͩ͠ɺ͜ͷͱ͖ ߋ ৽͞Εͨ௖
      ఺bi ʹ͍ͭͯɺnegative[bi]=true ͱ͠·͢ɻ·ͨɺnegative[ai] ͕ true ͷ৔߹ʹ͸ɺnegative[bi] Λ true ʹ
    ͠·͢ɻ

  ͦͯ͠ɺnegative[N] ͕ true ʹͳ͍ͬͯΔ৔߹ʹ͸ʮinfʯɺͦ͏Ͱͳ͍৔߹ʹ͸ −ans Λग़ྗ͠·͢ɻ͜ͷ໰୊ͷ
 ৔߹ʹ͸ɺ∞> −N min ci ͱͳΔΑ͏ʹઃఆ͢Ε͹े෼Ͱ͢ɻ͜ͷղ๏ͷ࣌ؒܭࢉྔ͸ O(NM) ͱͳΓɺे෼ؒ
 ʹ߹ ͍·͢ɻ


  C++ͷίʔυྫʢ௖఺൪߸Λ 0-indexed ͱ͢Δʣ



 1 using ll = long long;

 2 const ll INF = 1LL << 50;


 3


 4

 5 int main(void) {

 6     int N, M;

 7     cin >>  N >> M;


 8

 9     const int NMAX = 1000;

10     const int MMAX = 2000;

11     int a[MMAX], b[MMAX];

12     ll c[MMAX];


13

14     for (int i = 0; i < M; ++i) {
15         cin >> a[i] >> b[i] >> c[i];
16         c[i] = -c[i];
17     }


18

19     ll dist[NMAX];


20

21     for (int i = 0; i < N; ++i) {
22         dist[i] = INF;

23     }


24

25     dist[0] = 0;


26


27

28     for (int loop = 0; loop < N - 1; ++ loop) {

29         for (int i = 0; i < M; ++i) {


                                                  4

30             if (dist[a[i] - 1] == INF) continue;


31

32             if (dist[b[i] - 1] > dist[a[i] - 1] + c[i]) {

33                 dist[b[i] - 1] = dist[a[i] - 1] + c[i];

34             }

35         }

36     }


37

38     ll ans = dist[N - 1];


39


40

41     bool negative[NMAX];


42

43     for (int i = 0; i < N; ++i) {

44         negative[i] = false;

45     }


46

47     for (int loop = 0; loop < N ; ++ loop) {

48         for (int i = 0; i < M; ++i) {

49             if (dist[a[i] - 1] == INF) continue;


50

51             if (dist[b[i] - 1] > dist[a[i] - 1] + c[i]) {

52                 dist[b[i] - 1] = dist[a[i] - 1] + c[i];

53                 negative[b[i] - 1] = true;

54             }


55

56             if (negative[a[i] - 1] == true) {

57                 negative[b[i] - 1] = true;

58             }

59         }
60     }


61


62

63     if (negative[N - 1])
64         cout << "inf" << endl;

65     else
66         cout << -ans << endl;


67

68     return 0;

69 }





